use std::collections::HashSet;
use std::io::{self, Error, Write};
use walkdir::WalkDir;
fn main() -> io::Result<()> {
    if std::env::args().collect::<Vec<String>>().len() != 1 {
        eprintln!("Usage: Put beside YuanShen.exe and Double Click it.");
        return Ok(());
    }

    let binding = std::env::current_exe().unwrap();
    let folder_path = binding.parent().unwrap();

    if !folder_path.join("YuanShen.exe").exists() {
        return Err(Error::new(io::ErrorKind::Other, "chunks dir not found."));
    }

    let mut original_set: HashSet<String> = HashSet::new();
    for i in NAMES.lines() {
        original_set.insert(i.to_string());
    }

    let mut line = 0_usize;
    let mut user_set: HashSet<String> = HashSet::new();
    for entry in WalkDir::new(folder_path.join("chunks")) {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue, // 跳过无法读取的文件或目录
        };

        if entry.file_type().is_file() {
            if line % 40 == 0 {
                println!("Line: {line}");
            };
            line += 1;
            let file_path = entry.path();
            let file_name = file_path.file_name().unwrap().to_string_lossy();
            user_set.insert(file_name.to_string());
        }
    }

    let final_path = folder_path.join("result.txt");
    let mut buffer = std::fs::File::create(&final_path)?;

    let missing: HashSet<_> = original_set.difference(&user_set).collect();
    let extra: HashSet<_> = user_set.difference(&original_set).collect();
    buffer.write(b"+ means \"More than the standard value.\"\n- means \"Less than it\"\n\n")?;
    for i in missing {
        buffer.write(format!("-{}\n", i).as_bytes())?;
    }
    for i in extra {
        buffer.write(format!("+{}\n", i).as_bytes())?;
    }

    Ok(())
}

